using System;using System.IO;using System.Text;using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Threading;
namespace DonaldOnline {
public sealed class Pose {
 public static readonly System.Diagnostics.Stopwatch Clock=System.Diagnostics.Stopwatch.StartNew();
 public string Level;public long Sequence;public long Time;public string LeaveMap="";public uint DrawMask,ModelMask;public int Look=-1;public string Name="";public byte[] Matrix;public int Animation=-1;public int Portal=-1;public int WarpSeq;public string MapFile="";public Guid Session=Guid.Empty;public uint[] Gone=new uint[0];public int StarsEarned,StarsAck=-1;public uint[] Progress;public uint[] ItemStates;public uint[] Timer;public byte[] Camera;public int CameraLag;/* item claims (7.11.): own pickups, and from the host the ones it gave to the guest */public uint[] Claims,Grants;static readonly Guid LocalSession=Guid.NewGuid();
 public byte[] Encode(){using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(0x3A4B4344);w.Write(Sequence);w.Write(Level??"");w.Write(MapFile??"");w.Write((Session==Guid.Empty?LocalSession:Session).ToByteArray());if(Matrix==null||Matrix.Length!=88)throw new InvalidDataException("Matrix length");w.Write(Matrix);w.Write(Animation);w.Write(Portal);w.Write(WarpSeq);w.Write(Time);w.Write(LeaveMap??"");w.Write(DrawMask);w.Write(ModelMask);w.Write(Look);w.Write(Name??"");/* shared world events (4.11.) */uint[] gone=Gone??new uint[0];int count=Math.Min(gone.Length,8);w.Write((byte)count);for(int i=0;i<count;i++)w.Write(gone[i]);/* 65535 = not known yet */w.Write((ushort)(StarsEarned<0?65535:Math.Min(65534,StarsEarned)));w.Write((ushort)(StarsAck<0?65535:Math.Min(65534,StarsAck)));/* level progress words (5.11.) */w.Write((byte)(Progress==null?0:Math.Min(Progress.Length,8)));if(Progress!=null)for(int i=0;i<Math.Min(Progress.Length,8);i++)w.Write(Progress[i]);/* item animation states: pairs hash, state index (5.11.) */int ip=ItemStates==null?0:Math.Min(ItemStates.Length/2,4);w.Write((byte)ip);for(int i=0;i<ip;i++){w.Write(ItemStates[i*2]);w.Write((ushort)Math.Min(65535u,ItemStates[i*2+1]));}/* book timer words (6.11.) */w.Write((byte)(Timer==null?0:3));if(Timer!=null)for(int i=0;i<3;i++)w.Write(Timer[i]);/* game camera for a spectating partner (6.11.) */bool cam=Camera!=null&&Camera.Length==88;w.Write((byte)(cam?2:0));if(cam){w.Write(Camera);w.Write((short)Math.Max(-30000,Math.Min(30000,CameraLag)));}foreach(uint[] list in new[]{Claims,Grants}){int lc=list==null?0:Math.Min(list.Length,4);w.Write((byte)lc);for(int i=0;i<lc;i++)w.Write(list[i]);}return m.ToArray();}}
 // Player names: at most 16 printable characters.
 public static string CleanName(string n){var sb=new StringBuilder();foreach(char ch in n??"")if(!char.IsControl(ch)&&sb.Length<16)sb.Append(ch);return sb.ToString().Trim();}
 public static Pose Decode(byte[] data){if(data.Length>512)throw new InvalidDataException("Packet too large");using(var m=new MemoryStream(data))using(var r=new BinaryReader(m)){if(r.ReadInt32()!=0x3A4B4344)throw new InvalidDataException("Protocol mismatch");var p=new Pose();p.Sequence=r.ReadInt64();p.Level=r.ReadString();p.MapFile=r.ReadString();byte[] session=r.ReadBytes(16);if(session.Length!=16)throw new InvalidDataException("Session");p.Session=new Guid(session);if(p.Session==Guid.Empty)throw new InvalidDataException("Invalid session");if(p.MapFile.Length>28||!System.Text.RegularExpressions.Regex.IsMatch(p.MapFile,"^[A-Za-z0-9_]*$"))throw new InvalidDataException("Map");if(p.Level.Length>100)throw new InvalidDataException("Level name");p.Matrix=r.ReadBytes(88);p.Animation=r.ReadInt32();if(p.Animation < -1||p.Animation>4095)throw new InvalidDataException("Invalid animation");p.Portal=r.ReadInt32();if(p.Portal < -1||p.Portal>999)throw new InvalidDataException("Invalid portal");p.WarpSeq=r.ReadInt32();p.Time=r.ReadInt64();p.LeaveMap=r.ReadString();p.DrawMask=r.ReadUInt32();p.ModelMask=r.ReadUInt32();p.Look=r.ReadInt32();p.Name=CleanName(r.ReadString());int gone=r.ReadByte();if(gone>8)throw new InvalidDataException("World events");p.Gone=new uint[gone];for(int i=0;i<gone;i++)p.Gone[i]=r.ReadUInt32();p.StarsEarned=r.ReadUInt16();if(p.StarsEarned==65535)p.StarsEarned=-1;p.StarsAck=r.ReadUInt16();if(p.StarsAck==65535)p.StarsAck=-1;int pc=r.ReadByte();if(pc>8)throw new InvalidDataException("Progress");if(pc>0){p.Progress=new uint[pc];for(int i=0;i<pc;i++)p.Progress[i]=r.ReadUInt32();}int ip=r.ReadByte();if(ip>4)throw new InvalidDataException("Item states");if(ip>0){p.ItemStates=new uint[ip*2];for(int i=0;i<ip;i++){p.ItemStates[i*2]=r.ReadUInt32();p.ItemStates[i*2+1]=r.ReadUInt16();}}int tc=r.ReadByte();if(tc!=0&&tc!=3)throw new InvalidDataException("Timer");if(tc==3){p.Timer=new uint[3];for(int i=0;i<3;i++)p.Timer[i]=r.ReadUInt32();}int cf=r.ReadByte();if(cf>2)throw new InvalidDataException("Camera");if(cf>=1){p.Camera=r.ReadBytes(88);if(p.Camera.Length!=88)throw new InvalidDataException("Camera");for(int i=4;i<88;i+=4){float v=BitConverter.ToSingle(p.Camera,i);if(float.IsNaN(v)||float.IsInfinity(v)||Math.Abs(v)>1000000)throw new InvalidDataException("Camera");}if(cf==2)p.CameraLag=r.ReadInt16();}for(int li=0;li<2;li++){int lc=r.ReadByte();if(lc>4)throw new InvalidDataException("Claims");var list=new uint[lc];for(int i=0;i<lc;i++)list[i]=r.ReadUInt32();if(li==0)p.Claims=list;else p.Grants=list;}if(p.LeaveMap.Length>28||!System.Text.RegularExpressions.Regex.IsMatch(p.LeaveMap,"^[A-Za-z0-9_]*$"))throw new InvalidDataException("Leave map");if(p.Matrix.Length!=88||m.Position!=m.Length)throw new InvalidDataException("Invalid packet");if(BitConverter.ToUInt32(p.Matrix,0)>4)throw new InvalidDataException("Invalid matrix type");for(int i=4;i<88;i+=4){float v=BitConverter.ToSingle(p.Matrix,i);if(float.IsNaN(v)||float.IsInfinity(v)||Math.Abs(v)>1000000)throw new InvalidDataException("Invalid transform");}return p;}}
}
public sealed class RoomServer:IDisposable {
 readonly TcpListener listener;readonly object gate=new object();volatile bool stopping;Pose local,remote;DateTime lastPeer;Guid activePeer;public readonly string Token;public int Port{get;private set;}
 public RoomServer(){byte[] key=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(key);Token=BitConverter.ToString(key).Replace("-","").ToLowerInvariant();listener=new TcpListener(IPAddress.Loopback,0);listener.Start(8);Port=((IPEndPoint)listener.LocalEndpoint).Port;new Thread(Accept){IsBackground=true}.Start();}
 public Pose Local{set{lock(gate)local=value;}}public Pose Remote{get{lock(gate)return DateTime.UtcNow-lastPeer<TimeSpan.FromSeconds(3)?remote:null;}}
 void Accept(){while(!stopping)try{var client=listener.AcceptTcpClient();ThreadPool.QueueUserWorkItem(o=>Handle(client));}catch{if(!stopping)Thread.Sleep(50);}}
 void Handle(TcpClient client){using(client)try{client.ReceiveTimeout=3000;client.SendTimeout=3000;using(var s=client.GetStream()){while(!stopping){string header=ReadHeader(s);string[] lines=header.Split(new[]{"\r\n"},StringSplitOptions.None);if(lines[0]=="POST /frame/"+Token+" HTTP/1.1"||lines[0]=="GET /frame/"+Token+" HTTP/1.1"){if(!HandleFrame(s,lines))return;continue;}if(lines[0]!="POST /room/"+Token+" HTTP/1.1"){Reply(s,403,new byte[0]);return;}int length=-1;foreach(string line in lines){if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))length=int.Parse(line.Substring(15).Trim());}if(length<1||length>512){Reply(s,400,new byte[0]);return;}byte[] bytes=new byte[length];ReadExact(s,bytes);Pose incoming=Pose.Decode(bytes),outgoing;lock(gate){if(activePeer!=Guid.Empty&&activePeer!=incoming.Session&&DateTime.UtcNow-lastPeer<TimeSpan.FromSeconds(10)){Reply(s,409,new byte[0]);return;}/* the guest sends several requests at once, so an older pose may arrive after a newer one */if(remote==null||activePeer!=incoming.Session||incoming.Time>=remote.Time)remote=incoming;activePeer=incoming.Session;lastPeer=DateTime.UtcNow;outgoing=local;}Reply(s,outgoing==null?204:200,outgoing==null?new byte[0]:outgoing.Encode());}}}catch{}}
 // Spectator picture (7.11.): the guest uploads its frames (POST), the guest fetches the host's frames (GET, waits up to
 // 400 ms for a newer one than X-After). FrameSource = the host's own capture.
 public Func<VideoFrame> FrameSource;VideoFrame upFrame;public VideoFrame UpFrame{get{lock(gate)return upFrame;}}
 static string HeaderValue(string[] lines,string name){foreach(string l in lines)if(l.StartsWith(name+":",StringComparison.OrdinalIgnoreCase))return l.Substring(name.Length+1).Trim();return null;}
 bool HandleFrame(Stream s,string[] lines){long v;if(lines[0].StartsWith("POST",StringComparison.Ordinal)){int length;if(!int.TryParse(HeaderValue(lines,"Content-Length"),out length)||length<4||length>FrameClient.FrameLimit){Reply(s,400,new byte[0]);return false;}byte[] b=new byte[length];ReadExact(s,b);long seq,time;if(!long.TryParse(HeaderValue(lines,"X-Seq"),out seq)||!long.TryParse(HeaderValue(lines,"X-Time"),out time)||b[0]!=0xFF||b[1]!=0xD8){Reply(s,400,new byte[0]);return false;}long qpc;long.TryParse(HeaderValue(lines,"X-Qpc"),out qpc);lock(gate){if(upFrame==null||seq>upFrame.Seq||seq<upFrame.Seq-1000)upFrame=new VideoFrame{Seq=seq,Time=time,Qpc=qpc,Jpeg=b};}Reply(s,204,new byte[0]);return true;}
  long after=long.TryParse(HeaderValue(lines,"X-After"),out v)?v:0;var sw=System.Diagnostics.Stopwatch.StartNew();while(!stopping&&sw.ElapsedMilliseconds<400){var src=FrameSource;VideoFrame f=src==null?null:src();if(f!=null&&(f.Seq>after||f.Seq<after-1000)){byte[] h=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: image/jpeg\r\nContent-Length: "+f.Jpeg.Length+"\r\nX-Seq: "+f.Seq+"\r\nX-Time: "+f.Time+"\r\nX-Qpc: "+f.Qpc+"\r\nConnection: keep-alive\r\nCache-Control: no-store\r\n\r\n");s.Write(h,0,h.Length);s.Write(f.Jpeg,0,f.Jpeg.Length);return true;}Thread.Sleep(4);}Reply(s,204,new byte[0]);return true;} static string ReadHeader(Stream s){var b=new MemoryStream();int tail=0;while(b.Length<4096){int c=s.ReadByte();if(c<0)throw new EndOfStreamException();b.WriteByte((byte)c);tail=(tail<<8)|c;if(tail==0x0D0A0D0A)return Encoding.ASCII.GetString(b.ToArray());}throw new InvalidDataException("Header too large");}
 static void ReadExact(Stream s,byte[] b){int off=0;while(off<b.Length){int n=s.Read(b,off,b.Length-off);if(n==0)throw new EndOfStreamException();off+=n;}}
 static void Reply(Stream s,int status,byte[] b){byte[] h=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" "+(status==200?"OK":status==204?"No Content":"Rejected")+"\r\nContent-Type: application/octet-stream\r\nContent-Length: "+b.Length+"\r\nConnection: keep-alive\r\nCache-Control: no-store\r\n\r\n");s.Write(h,0,h.Length);s.Write(b,0,b.Length);}
 public void Dispose(){stopping=true;listener.Stop();}
}
public static class RoomClient {
 /* test builds: extra delay like a slow internet connection (settings TestLagMs=50-150 = random one-way delay per request) */public static int TestLagMin,TestLagMax;[ThreadStatic]static Random lagRandom;static void Lag(){if(TestLagMax<=0)return;if(lagRandom==null)lagRandom=new Random(Guid.NewGuid().GetHashCode());Thread.Sleep(lagRandom.Next(TestLagMin,TestLagMax+1));}
 public static Pose Exchange(string endpoint,string token,Pose local){Lag();try{return ExchangeNow(endpoint,token,local);}finally{Lag();}}
 static Pose ExchangeNow(string endpoint,string token,Pose local){Uri uri=new Uri(endpoint);if(uri.Scheme!="https"&&!(uri.Scheme=="http"&&uri.IsLoopback))throw new ArgumentException("HTTPS required");if(token.Length!=64||!System.Text.RegularExpressions.Regex.IsMatch(token,"^[0-9a-f]{64}$"))throw new ArgumentException("Invalid invite");var req=(HttpWebRequest)WebRequest.Create(new Uri(uri,"/room/"+token));req.Method="POST";req.ContentType="application/octet-stream";req.Timeout=3500;req.ReadWriteTimeout=3500;req.KeepAlive=true;req.Proxy=null;req.ServicePoint.Expect100Continue=false;byte[] b=local.Encode();req.ContentLength=b.Length;using(var s=req.GetRequestStream())s.Write(b,0,b.Length);using(var response=(HttpWebResponse)req.GetResponse()){if(response.StatusCode==HttpStatusCode.NoContent)return null;if(response.ContentLength>512)throw new InvalidDataException();using(var s=response.GetResponseStream())using(var m=new MemoryStream()){var buffer=new byte[256];int n;while((n=s.Read(buffer,0,buffer.Length))>0){m.Write(buffer,0,n);if(m.Length>512)throw new InvalidDataException();}return Pose.Decode(m.ToArray());}}}
}
}
